// Home page helper: the selected service day and everything the header, agenda and revisit cards show.
// Runs on visits.onDataQuerySuccess, Home onPageLoad and scheduleDay.onSelect.
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const all = queries.visits.data || [];
const today = new Date().toLocaleDateString('en-CA');
// DatePickerV2 exposes `value` (ISO string, local offset) — take its calendar date.
const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(components.scheduleDay?.value || ''));
const picked = m ? m[1] : '';
const fallback = all.some(v => v.service_date === today) ? today
  : (all.filter(v => !['Completed', 'Cancelled'].includes(v.status)).slice().sort((a, b) => a.service_date.localeCompare(b.service_date))[0]?.service_date || today);
const date = picked || fallback;
const vs = all.filter(v => v.service_date === date).slice().sort((a, b) => a.start_time.localeCompare(b.start_time));
const label = new Date(date + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
const mono = s => '<span style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;">' + e(s) + '</span>';
const shown = vs.slice(0, 3); // owner's decision: keep the 3-visit cap
const rows = shown.map(v => {
  const tasks = v.tasks || [];
  const done = tasks.filter(t => t.status === 'Done').length;
  return {
    id: v.id, empty: false, start_time: v.start_time, site_name: v.site_name,
    metaHtml: mono(v.reference) + ' · ' + e(v.crew),
    status: v.status,
    statusColor: v.status === 'Completed' ? 'var(--cc-success-systemStatus)' : 'var(--cc-primary-brand)',
    progress: Math.round(100 * done / Math.max(1, tasks.length)),
    areas: done + '/' + tasks.length + ' areas'
  };
});
if (!rows.length) rows.push({ id: null, empty: true, start_time: '', site_name: 'No visits scheduled for this date.', metaHtml: 'Open All visits to plan the day.', status: '', statusColor: 'var(--cc-primary-brand)', progress: 0, areas: '' });
const rev = all.filter(v => v.status === 'Revisit' || (v.tasks || []).some(t => t.status === 'Needs revisit'));
const r = rev[0];
return {
  date, label,
  count: vs.length,
  crews: new Set(vs.map(v => v.crew)).size,
  completed: vs.filter(v => v.status === 'Completed').length,
  visits: rows,
  capacityNote: vs.length > 3 ? 'First 3 visits shown for this date. All visits contains the complete schedule.' : 'Manual crew scheduling · Start times shown; travel and service duration are not calculated.',
  revisitCount: rev.length,
  revisitId: r ? r.id : null,
  revisitSite: r ? r.site_name : '',
  revisitMetaHtml: r ? mono(r.reference) + ' · ' + e(r.crew) : '',
  revisitNote: r ? (((r.tasks || []).find(t => t.status === 'Needs revisit') || {}).note || 'Open the visit history for the follow-up details.') : 'No open revisit requests. Completed work stays in the visit record.',
  revisitFlagged: r ? 'Areas flagged: ' + (r.tasks || []).filter(t => t.status === 'Needs revisit').length : ''
};

// Visit page helper: the selected visit's site details and its activity history.
// Runs on visits.onDataQuerySuccess, sites.onDataQuerySuccess and Visit onPageLoad.
const v = (queries.visits.data || []).find(v => v.id === variables.visitId);
const s = v ? (queries.sites.data || []).find(s => s.name === v.site_name) : null;
return {
  has: !!v,
  address: (s && s.address) || '',
  instructions: (s && s.instructions) || '',
  contact: (s && s.contact) || '',
  history: ((v && v.history) || []).slice().reverse().map(h => ({ event: h.event || '', note: h.note || '', at: h.at || '' }))
};
